import re
from functools import cmp_to_key

def _parse(v):
    core = v.split('+', 1)[0]
    if '-' in core:
        main, pre = core.split('-', 1)
    else:
        main, pre = core, None
    major, minor, patch = (int(x) for x in main.split('.'))
    pre_ids = pre.split('.') if pre is not None else None
    return (major, minor, patch, pre_ids)

def _cmp_pre(a, b):
    if a is None and b is None:
        return 0
    if a is None:
        return 1
    if b is None:
        return -1
    for x, y in zip(a, b):
        if x == y:
            continue
        x_num = x.isdigit()
        y_num = y.isdigit()
        if x_num and y_num:
            xi, yi = int(x), int(y)
            if xi != yi:
                return -1 if xi < yi else 1
            continue
        if x_num and not y_num:
            return -1
        if y_num and not x_num:
            return 1
        return -1 if x < y else 1
    if len(a) == len(b):
        return 0
    return -1 if len(a) < len(b) else 1

def _cmp(v1, v2):
    m1, n1, p1, pre1 = _parse(v1)
    m2, n2, p2, pre2 = _parse(v2)
    if m1 != m2:
        return -1 if m1 < m2 else 1
    if n1 != n2:
        return -1 if n1 < n2 else 1
    if p1 != p2:
        return -1 if p1 < p2 else 1
    return _cmp_pre(pre1, pre2)

def semver_sort(versions):
    return sorted(versions, key=cmp_to_key(lambda a, b: _cmp(a, b)))

